const view=document.getElementById('view');
const vctx=view.getContext('2d');
let base=null, original=null, mode='crop', drag=null, cropRect=null;
const $=id=>document.getElementById(id);
function say(t){$('msg').textContent=t;}
function cloneCanvas(c){const n=document.createElement('canvas');n.width=c.width;n.height=c.height;n.getContext('2d').drawImage(c,0,0);return n;}
function unit(){return Math.max(base.width,base.height)/600;}
function render(){
 if(!base)return;
 if(view.width!==base.width||view.height!==base.height){view.width=base.width;view.height=base.height;}
 vctx.clearRect(0,0,view.width,view.height);
 vctx.drawImage(base,0,0);
 if(mode==='crop'&&cropRect){
  const r=cropRect;
  vctx.save();vctx.fillStyle='rgba(0,0,0,0.5)';
  vctx.fillRect(0,0,view.width,r.y);
  vctx.fillRect(0,r.y+r.h,view.width,view.height-r.y-r.h);
  vctx.fillRect(0,r.y,r.x,r.h);
  vctx.fillRect(r.x+r.w,r.y,view.width-r.x-r.w,r.h);
  vctx.strokeStyle='#fff';vctx.lineWidth=2*unit();vctx.setLineDash([6*unit(),4*unit()]);
  vctx.strokeRect(r.x,r.y,r.w,r.h);vctx.restore();
 }
 if(mode==='arrow'&&drag){drawArrow(vctx,drag.x0,drag.y0,drag.x1,drag.y1);}
}
function drawArrow(ctx,x0,y0,x1,y1){
 const w=4*unit()*parseFloat($('size').value);
 const dx=x1-x0,dy=y1-y0,len=Math.hypot(dx,dy);
 if(len<2)return;
 const ang=Math.atan2(dy,dx);
 const head=Math.min(len,w*4.5);
 ctx.save();
 ctx.strokeStyle=$('color').value;ctx.fillStyle=$('color').value;
 ctx.lineWidth=w;ctx.lineCap='round';
 ctx.beginPath();ctx.moveTo(x0,y0);ctx.lineTo(x1-Math.cos(ang)*head*0.6,y1-Math.sin(ang)*head*0.6);ctx.stroke();
 ctx.beginPath();ctx.moveTo(x1,y1);
 ctx.lineTo(x1-head*Math.cos(ang-0.4),y1-head*Math.sin(ang-0.4));
 ctx.lineTo(x1-head*Math.cos(ang+0.4),y1-head*Math.sin(ang+0.4));
 ctx.closePath();ctx.fill();ctx.restore();
}
function pos(e){
 const r=view.getBoundingClientRect();
 return {x:Math.max(0,Math.min(view.width,(e.clientX-r.left)*view.width/r.width)),y:Math.max(0,Math.min(view.height,(e.clientY-r.top)*view.height/r.height))};
}
function setMode(m){
 mode=m;drag=null;
 for(const k of ['crop','arrow','text']){$('m-'+k).setAttribute('aria-pressed',String(k===m));}
 $('textrow').hidden=m!=='text';
 $('croprow').hidden=m!=='crop';
 $('hint').textContent=m==='crop'?'Drag on the photo to choose the part to keep, then press Apply crop.':m==='arrow'?'Drag on the photo from where the arrow starts to where it points.':'Type your text, then click on the photo where it should go.';
 render();
}
function setImage(c,note){
 base=c;cropRect=null;drag=null;
 $('apply').disabled=true;
 render();
 say(note);
}
function enable(){
 $('tools').hidden=false;$('save').disabled=false;$('reset').disabled=false;
}
view.addEventListener('pointerdown',e=>{
 if(!base)return;
 const p=pos(e);
 if(mode==='text'){
  const t=$('txt').value;
  if(!t.trim()){say('Type some text first, then click on the photo.');return;}
  const ctx=base.getContext('2d');
  const px=Math.round(24*unit()*parseFloat($('size').value));
  ctx.save();ctx.font='600 '+px+'px "Segoe UI",Arial,sans-serif';ctx.textBaseline='middle';
  ctx.lineJoin='round';ctx.lineWidth=px/6;
  const col=$('color').value;
  ctx.strokeStyle=(col==='#ffffff'||col==='#f2c200')?'#000000':'#ffffff';
  ctx.strokeText(t,p.x,p.y);ctx.fillStyle=col;ctx.fillText(t,p.x,p.y);ctx.restore();
  render();say('Text added.');return;
 }
 view.setPointerCapture(e.pointerId);
 drag={x0:p.x,y0:p.y,x1:p.x,y1:p.y};
 if(mode==='crop'){cropRect=null;$('apply').disabled=true;}
});
view.addEventListener('pointermove',e=>{
 if(!drag)return;
 const p=pos(e);drag.x1=p.x;drag.y1=p.y;
 if(mode==='crop'){
  cropRect={x:Math.min(drag.x0,p.x),y:Math.min(drag.y0,p.y),w:Math.abs(p.x-drag.x0),h:Math.abs(p.y-drag.y0)};
 }
 render();
});
view.addEventListener('pointerup',e=>{
 if(!drag)return;
 const d=drag;drag=null;
 if(mode==='arrow'){
  if(Math.hypot(d.x1-d.x0,d.y1-d.y0)<5){render();say('Drag to draw an arrow.');return;}
  drawArrow(base.getContext('2d'),d.x0,d.y0,d.x1,d.y1);render();say('Arrow added.');
 }else if(mode==='crop'){
  if(cropRect&&cropRect.w>=5&&cropRect.h>=5){$('apply').disabled=false;say('Crop area chosen. Press Apply crop to keep it.');}
  else{cropRect=null;$('apply').disabled=true;render();say('Drag a larger area to crop.');}
 }
});
view.addEventListener('pointercancel',()=>{drag=null;render();});
$('apply').addEventListener('click',()=>{
 if(!cropRect)return;
 const r=cropRect;
 const x=Math.round(r.x),y=Math.round(r.y),w=Math.max(1,Math.round(r.w)),h=Math.max(1,Math.round(r.h));
 const n=document.createElement('canvas');n.width=w;n.height=h;
 n.getContext('2d').drawImage(base,x,y,w,h,0,0,w,h);
 setImage(n,'Cropped to '+w+' × '+h+' pixels.');
});
$('rotate').addEventListener('click',()=>{
 if(!base)return;
 const n=document.createElement('canvas');n.width=base.height;n.height=base.width;
 const c=n.getContext('2d');c.translate(n.width,0);c.rotate(Math.PI/2);c.drawImage(base,0,0);
 setImage(n,'Rotated 90° clockwise.');
});
$('reset').addEventListener('click',()=>{
 if(!original)return;
 setImage(cloneCanvas(original),'Back to the photo as you opened it.');
});
for(const k of ['crop','arrow','text']){$('m-'+k).addEventListener('click',()=>setMode(k));}
$('open').addEventListener('click',async()=>{
 try{
  const f=await tessera.pickFile();
  if(!f){say('No photo chosen.');return;}
  const img=new Image();
  img.src=await tessera.assetUrl(f.id);
  await img.decode();
  const c=document.createElement('canvas');
  c.width=img.naturalWidth;c.height=img.naturalHeight;
  c.getContext('2d').drawImage(img,0,0);
  original=cloneCanvas(c);
  enable();setMode('crop');
  setImage(c,'Opened '+f.name+' ('+c.width+' × '+c.height+' pixels).');
 }catch(err){say('Could not open the photo: '+((err&&err.message)||'unknown problem')+'. Try another photo.');}
});
$('save').addEventListener('click',async()=>{
 if(!base)return;
 try{
  const saved=await tessera.saveFile({name:'photo-markup',type:'image/png',bytesBase64:base.toDataURL('image/png').split(',')[1]});
  say(saved?'Image saved.':'Not saved. You chose not to save the image.');
 }catch(err){say('Could not save: '+((err&&err.message)||'unknown problem')+'.');}
});
setMode('crop');

